CREATE TABLE IF NOT EXISTS admins (id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS providers (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'openai_compatible',base_url TEXT NOT NULL,api_key_enc TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,priority INTEGER NOT NULL DEFAULT 100,weight INTEGER NOT NULL DEFAULT 100,timeout_seconds INTEGER NOT NULL DEFAULT 120,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS provider_models (id INTEGER PRIMARY KEY AUTOINCREMENT,provider_id INTEGER NOT NULL,public_model TEXT NOT NULL,upstream_model TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,UNIQUE(provider_id,public_model),FOREIGN KEY(provider_id) REFERENCES providers(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quota_windows (id INTEGER PRIMARY KEY AUTOINCREMENT,provider_id INTEGER NOT NULL,label TEXT NOT NULL,window_seconds INTEGER NOT NULL,token_limit INTEGER NOT NULL DEFAULT 0,request_limit INTEGER NOT NULL DEFAULT 0,reset_mode TEXT NOT NULL DEFAULT 'rolling',reset_anchor INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(provider_id) REFERENCES providers(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS client_keys (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,key_prefix TEXT NOT NULL,key_hash TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,last_used_at INTEGER);
CREATE TABLE IF NOT EXISTS usage_events (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id TEXT NOT NULL,provider_id INTEGER,client_key_id INTEGER,model TEXT NOT NULL,upstream_model TEXT,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,total_tokens INTEGER NOT NULL DEFAULT 0,usage_source TEXT NOT NULL DEFAULT 'provider',status_code INTEGER NOT NULL DEFAULT 0,latency_ms INTEGER NOT NULL DEFAULT 0,success INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,FOREIGN KEY(provider_id) REFERENCES providers(id) ON DELETE SET NULL,FOREIGN KEY(client_key_id) REFERENCES client_keys(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_usage_provider_time ON usage_events(provider_id,created_at);
CREATE INDEX IF NOT EXISTS idx_usage_client_time ON usage_events(client_key_id,created_at);
CREATE INDEX IF NOT EXISTS idx_usage_model_time ON usage_events(model,created_at);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO settings(key,value) VALUES('routing_strategy','priority');
